import React, { useEffect, useState } from 'react'

const ERROR_IMG_SRC =
  'data:image/svg+xml;base64,'

export function ImageWithFallback(props: React.ImgHTMLAttributes<HTMLImageElement>) {
  const [didError, setDidError] = useState(false)
  const { src, alt, style, className, ...rest } = props

  // A failure is tied to ONE src. Without this reset, an early failure (e.g. an
  // empty src on first paint while data loads) permanently poisoned the
  // component — the placeholder stuck even after the real URL arrived.
  useEffect(() => {
    setDidError(false)
  }, [src])

  const handleError = () => {
    setDidError(true)
  }

  // No source yet (data still loading) — render the reserved space without an
  // <img> so an empty src can't fire a spurious error.
  if (!src) {
    return (
      <div
        className={`inline-block bg-gray-100 align-middle ${className ?? ''}`}
        style={style}
        aria-label={alt}
      />
    )
  }

  return didError ? (
    <div
      className={`inline-block bg-gray-100 text-center align-middle ${className ?? ''}`}
      style={style}
    >
      <div className="flex items-center justify-center w-full h-full">
        <img src={ERROR_IMG_SRC} alt="Error loading image" {...rest} data-original-url={src} />
      </div>
    </div>
  ) : (
    <img src={src} alt={alt} className={className} style={style} {...rest} onError={handleError} />
  )
}
